/// Generate a boilerplate block plugin Rust source file (native .so/.dylib).
///
/// The generated file implements the `Plugin` trait with stub `infer_shape`,
/// `param_count`, and `codegen` methods. Registration is handled automatically
/// via the `register_plugin!` macro, and the FFI export via `export_plugin!`.
///
/// # Arguments
/// * `block_name` - The PascalCase block type name (e.g., "MyCustomLayer")
///
/// # Returns
/// The generated Rust source code as a String.
pub fn generate_plugin_file(block_name: &str) -> String {
    let snake = to_snake_case(block_name);

    format!(
        r#"/// {name} block plugin
///
/// Auto-generated by `mlmd plugin new`.
/// Fill in the shape inference and codegen implementations.

use mlmd_plugin_api::*;

struct {name};

impl Plugin for {name} {{
    fn name(&self) -> &'static str {{ "{name}" }}

    fn params(&self) -> Vec<ParamSpec> {{
        vec![
            // TODO: Add your params here
            // ParamSpec::number("input_dim").required(),
        ]
    }}

    fn infer_shape(&self, inputs: &[Shape], _params: &HashMap<String, ParamValue>) -> Result<Vec<Shape>, String> {{
        if inputs.is_empty() {{
            return Err("{name} requires at least one input".to_string());
        }}
        // TODO: Implement shape inference logic
        Ok(vec![inputs[0].clone()]) // Passthrough by default
    }}

    fn param_count(&self, _inputs: &[Shape], _params: &HashMap<String, ParamValue>) -> Option<usize> {{
        // TODO: Compute parameter count if applicable
        None
    }}

    fn codegen(&self, target: &str, block: &Block, input_vars: &[String], output_vars: &[String]) -> Option<BlockCodegenResult> {{
        match target {{
            "pytorch" => Some(BlockCodegenResult::stateless(
                format!("{{}} = {{}}", output_vars[0], input_vars[0]),
            )),
            "keras" => Some(BlockCodegenResult::stateless(
                format!("{{}} = {{}}", output_vars[0], input_vars[0]),
            )),
            "candle" => Some(BlockCodegenResult::stateless(
                format!("{{}} = {{}}", output_vars[0], input_vars[0]),
            )),
            _ => None,
        }}
    }}
}}

register_plugin!({name});
export_plugin!({name});

#[cfg(test)]
mod tests {{
    use super::*;

    #[test]
    fn test_{snake}_shape_inference() {{
        let plugin = {name};
        let params = HashMap::new();
        let result = plugin.infer_shape(&[vec![3, 32, 32]], &params);
        assert!(result.is_ok());
    }}
}}
"#,
        name = block_name,
        snake = snake,
    )
}

