/// Generate a `Cargo.toml` for a new plugin project.
///
/// The generated template depends on `mlmd-plugin-api` and `mlmd-core` via
/// relative paths.  You may need to adjust these paths depending on where
/// mlmd lives in your project.
///
/// # Arguments
/// * `plugin_name` - The kebab-case package name (e.g. "my-cool-plugin")
/// * `block_name` - The PascalCase block type name (e.g. "MyCoolLayer")
pub fn generate_plugin_cargo_toml(plugin_name: &str, block_name: &str) -> String {
    format!(
        r#"[package]
name = "{plugin_name}"
version = "0.1.0"
edition = "2021"
description = "NNML block plugin: {block_name}"

[lib]
crate-type = ["lib", "cdylib"]

[dependencies]
# TODO: Update these paths to point to your local mlmd checkout, or use
# published versions from crates.io once available.
mlmd-core = {{ path = "../mlmd-core" }}
mlmd-plugin-api = {{ path = "../mlmd-plugin-api" }}
"#,
        plugin_name = plugin_name,
        block_name = block_name,
    )
}

/// Convert a kebab-case string to PascalCase.
///
/// # Examples
///
/// ```
/// use mlmd_core::plugin::scaffold::kebab_to_pascal;
/// assert_eq!(kebab_to_pascal("my-cool-plugin"), "MyCoolPlugin");
/// assert_eq!(kebab_to_pascal("mlmd-example-plugin"), "MlmdExamplePlugin");
/// ```
pub fn kebab_to_pascal(s: &str) -> String {
    s.split('-')
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            match chars.next() {
                None => String::new(),
                Some(first) => first.to_uppercase().to_string() + chars.as_str(),
            }
        })
        .collect()
}

/// Convert a PascalCase string to snake_case.
///
/// # Examples
///
/// ```
/// use mlmd_core::plugin::scaffold::to_snake_case;
/// assert_eq!(to_snake_case("MyCustomLayer"), "my_custom_layer");
/// assert_eq!(to_snake_case("AttentionHead"), "attention_head");
/// assert_eq!(to_snake_case("ValidBlock"), "valid_block");
/// ```
pub fn to_snake_case(s: &str) -> String {
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_uppercase() {
            if i > 0 {
                result.push('_');
            }
            result.push(c.to_lowercase().next().unwrap());
        } else {
            result.push(c);
        }
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_simple_block() {
        let code = generate_plugin_file("MyCustomLayer");
        assert!(code.contains("MyCustomLayer"));
        assert!(code.contains("infer_shape"));
        assert!(code.contains("register_plugin!(MyCustomLayer)"));
        assert!(code.contains("fn codegen("));
    }

    #[test]
    fn test_generate_snake_case_name() {
        let code = generate_plugin_file("AttentionHead");
        assert!(code.contains("AttentionHead"));
        assert!(code.contains("attention_head"));
    }

    #[test]
    fn test_generate_valid_rust() {
        // Verify the generated code uses the new Plugin trait pattern
        let code = generate_plugin_file("ValidBlock");
        assert!(code.contains("impl Plugin for ValidBlock"));
        assert!(code.contains("register_plugin!(ValidBlock)"));
    }

    #[test]
    fn test_to_snake_case_basic() {
        assert_eq!(to_snake_case("MyCustomLayer"), "my_custom_layer");
    }

    #[test]
    fn test_to_snake_case_single_word() {
        assert_eq!(to_snake_case("Linear"), "linear");
    }

    #[test]
    fn test_to_snake_case_acronym() {
        assert_eq!(to_snake_case("LSTM"), "l_s_t_m");
    }

    #[test]
    fn test_kebab_to_pascal_basic() {
        assert_eq!(kebab_to_pascal("my-cool-plugin"), "MyCoolPlugin");
    }

    #[test]
    fn test_kebab_to_pascal_single() {
        assert_eq!(kebab_to_pascal("plugin"), "Plugin");
    }

    #[test]
    fn test_kebab_to_pascal_trailing_hyphen() {
        assert_eq!(kebab_to_pascal("my-plugin-"), "MyPlugin");
    }

    #[test]
    fn test_generate_cargo_toml() {
        let toml = generate_plugin_cargo_toml("my-cool-plugin", "MyCoolPlugin");
        assert!(toml.contains(r#"name = "my-cool-plugin""#));
        assert!(toml.contains("mlmd-core"));
        assert!(toml.contains("mlmd-plugin-api"));
        assert!(toml.contains("cdylib"));
    }
}
